from pathlib import Path
import json
R=Path(__file__).resolve().parents[1]/'shared'
def save(name,data):(R/name).write_text(json.dumps(data,indent=2,ensure_ascii=False)+'\n')
text={'type':'string','minLength':1}
localized={'type':'object','required':['es','en'],'properties':{'es':text,'en':text},'additionalProperties':False}
save('catalog.schema.json',{'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:simplesoft:chords:catalog:1','title':'SimpleSoft Chords catalog v1','type':'object','required':['schemaVersion','catalogVersion','midiMin','midiMax','tuningA4','types'],'properties':{'schemaVersion':{'const':1},'catalogVersion':text,'midiMin':{'const':48},'midiMax':{'const':72},'tuningA4':{'const':440},'types':{'type':'array','items':{'type':'object','required':['id','family','names','symbol','semitones','degrees','aliases','explanationKey'],'properties':{'id':{'type':'string','pattern':'^[a-z][a-z0-9-]*$'},'family':text,'names':localized,'symbol':{'type':'string'},'semitones':{'type':'array','minItems':2,'uniqueItems':True,'items':{'type':'integer','minimum':0,'maximum':24}},'degrees':{'type':'array','minItems':2,'items':{'type':'integer','minimum':1,'maximum':15}},'aliases':{'type':'array','uniqueItems':True,'items':text},'explanationKey':text},'additionalProperties':False}}},'additionalProperties':False})
save('i18n.schema.json',{'$schema':'https://json-schema.org/draft/2020-12/schema','$id':'urn:simplesoft:chords:i18n:1','type':'object','required':['schemaVersion','es','en'],'properties':{'schemaVersion':{'const':1},'es':{'type':'object','additionalProperties':text},'en':{'type':'object','additionalProperties':text}},'additionalProperties':False})
save('examples.json',{'schemaVersion':1,'catalogVersion':'0.1.0','positionCases':[{'type':'minor','root':50,'notes':[50,53,57],'spellingsEn':['D3','F3','A3']},{'type':'dim7','root':48,'notes':[48,51,54,57],'spellingsEn':['C3','E♭3','G♭3','B♭♭3']},{'type':'thirteen','root':48,'notes':[48,52,55,58,62,65,69]},{'type':'maj7','root':54,'notes':[54,58,61,65],'spellingsEn':['F♯3','A♯3','C♯4','E♯4']}],'validationCases':[{'type':'minor','root':50,'selected':[50,53,57],'correct':True},{'type':'minor','root':50,'selected':[50,53],'correct':False},{'type':'minor','root':50,'selected':[50,53,57,69],'correct':False},{'type':'minor','root':50,'selected':[62,65,69],'correct':False}],'invalidPositionCases':[{'type':'thirteen','root':52,'reason':'max MIDI 73 exceeds 72'},{'type':'add9','root':60,'reason':'max MIDI 74 exceeds 72'}],'noteFilterCases':[{'white':True,'twoOctaves':False,'notes':[48,50,52,53,55,57,59]},{'white':False,'twoOctaves':False,'notes':list(range(48,60))},{'white':True,'twoOctaves':True,'notes':[48,50,52,53,55,57,59,60,62,64,65,67,69,71,72]}],'equivalentSoundCases':[{'a':{'type':'sus2','root':48},'b':{'type':'sus4','root':55},'samePitchClasses':True},{'a':{'type':'aug','root':48},'b':{'type':'aug','root':52},'samePitchClasses':True}]})
